import {inject} from '@angular/core';
import {HttpClient} from '@angular/common/http';
import {Router} from '@angular/router';
import {catchError, map, of} from 'rxjs';

export const authGuard = () => {
  const http = inject(HttpClient);
  const router = inject(Router);

  return http.get('http://localhost:10032/api/users/me').pipe(
    map(() => true),
    catchError(() => {
      router.navigate(['/login']);
      return of(false);
    })
  );
};

import {HttpInterceptorFn} from '@angular/common/http';

export const credentialsInterceptor: HttpInterceptorFn = (req, next) => {
  if (req.url.startsWith('http://localhost:10032')) {
    return next(req.clone({withCredentials: true}));
  }
  return next(req);
};

import { Component, inject, OnDestroy, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { debounceTime, distinctUntilChanged, switchMap, takeUntil, catchError } from 'rxjs/operators';
import { of } from 'rxjs';
import { BookSearchService, BookSearchResult } from '../../services/book-search.service';
import { LibraryService, LibraryBook, LibraryFilter } from '../../services/library.service';
import { EpubStorageService } from '../../services/epub-storage.service';
import { EpubReaderComponent } from '../epub-reader/epub-reader.component';

@Component({
  selector: 'app-biblioteka',
  imports: [CommonModule, FormsModule, EpubReaderComponent],
  templateUrl: './biblioteka.component.html',
  styleUrl: './biblioteka.component.scss',
})
export class BibliotekaPuslapis implements OnDestroy {
  private readonly bookSearch = inject(BookSearchService);
  private readonly libraryService = inject(LibraryService);
  private readonly epubStorage = inject(EpubStorageService);
  private readonly searchSubject = new Subject<string>();
  private readonly destroy$ = new Subject<void>();

  searchQuery = '';
  searchResults: BookSearchResult[] = [];
  isSearchLoading = false;
  hasSearched = false;
  searchError = '';

  library = signal<LibraryBook[]>([]);
  filters = signal<LibraryFilter>({
    title: '',
    author: '',
    progress: undefined
  });
  isLibraryLoading = signal(false);
  libraryError = signal('');

  addingBookKey = signal<string | null>(null);
  uploadingKey = signal<string | null>(null);

  // Keys of books that have EPUB stored locally
  localEpubKeys = signal<Set<string>>(new Set());

  epubReaderKey = signal<string | null>(null);
  epubReaderTitle = signal('');
  epubReaderListId = signal<number | null>(null);
  epubReaderPageCount = signal<number | null>(null);

  activeFilter = signal<string>('VISI');

  constructor() {
    this.searchSubject
      .pipe(
        debounceTime(300),
        distinctUntilChanged(),
        switchMap(query => {
          this.isSearchLoading = true;
          this.hasSearched = true;
          this.searchError = '';
          this.searchResults = [];
          return this.bookSearch.search(query).pipe(
            catchError(() => {
              this.searchError = 'Nepavyko įkrauti rezultatų. Bandykite dar kartą.';
              return of([]);
            }),
          );
        }),
        takeUntil(this.destroy$),
      )
      .subscribe(results => {
        this.searchResults = results;
        this.isSearchLoading = false;
      });

    this.loadLibrary();
    this.loadLocalEpubKeys();
  }

  applyFilters(): void {
    const filterRequest: LibraryFilter = {};

    if (this.filters().title?.trim()) {
      filterRequest.title = this.filters().title;
    }
    if (this.filters().author?.trim()) {
      filterRequest.author = this.filters().author;
    }
    if (this.filters().progress !== undefined && this.filters().progress !== null) {
      filterRequest.progress = this.filters().progress;
    }

    this.libraryService.filterLibrary(filterRequest).subscribe({
      next: (library) => {
        this.library.set(library);
      },
      error: (error) => {
        console.error('Error filtering library:', error);
      }
    });
  }

  clearFilters(): void {
    this.filters.set({
      title: '',
      author: '',
      progress: undefined
    });
    this.loadLibrary();
  }

  private async loadLocalEpubKeys(): Promise<void> {
    const keys = await this.epubStorage.getAllKeys();
    this.localEpubKeys.set(new Set(keys));
  }

  onSearch(): void {
    const query = this.searchQuery.trim();
    if (!query) return;
    this.searchSubject.next(query);
  }

  onSearchKeydown(event: KeyboardEvent): void {
    if (event.key === 'Enter') this.onSearch();
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.searchResults = [];
    this.hasSearched = false;
    this.searchError = '';
  }

  loadLibrary(): void {
    this.isLibraryLoading.set(true);
    this.libraryService.getLibrary().subscribe({
      next: books => {
        this.library.set(books);
        this.isLibraryLoading.set(false);
      },
      error: () => {
        this.libraryError.set('Nepavyko įkrauti bibliotekos.');
        this.isLibraryLoading.set(false);
      },
    });
  }

  addToLibrary(book: BookSearchResult): void {
    this.addingBookKey.set(book.key);
    this.libraryService
      .addBook({
        olId: book.key,
        title: book.title,
        author: book.authors[0] ?? null,
        coverUrl: book.coverUrl,
        pageCount: book.pageCount,
        status: 'WANT_TO_READ',
        genre: book.genre,
      })
      .subscribe({
        next: added => {
          this.library.update(lib => [...lib, added]);
          this.addingBookKey.set(null);
        },
        error: err => {
          const msg = err?.error?.message ?? 'Nepavyko pridėti knygos.';
          alert(msg);
          this.addingBookKey.set(null);
        },
      });
  }

  isInLibrary(book: BookSearchResult): boolean {
    return this.library().some(b => b.olId === book.key);
  }

  hasLocalEpub(book: LibraryBook): boolean {
    return this.localEpubKeys().has(book.olId);
  }

  async onEpubFileSelected(event: Event, book: LibraryBook): Promise<void> {
    const input = event.target as HTMLInputElement;
    const file = input.files?.[0];
    if (!file) return;

    this.uploadingKey.set(book.olId);
    try {
      await this.epubStorage.save(book.olId, file);
      this.localEpubKeys.update(keys => new Set([...keys, book.olId]));
    } catch {
      alert('Nepavyko išsaugoti EPUB failo.');
    } finally {
      this.uploadingKey.set(null);
      input.value = '';
    }
  }

  openEpubReader(book: LibraryBook): void {
    this.epubReaderKey.set(book.olId);
    this.epubReaderTitle.set(book.title);
    this.epubReaderListId.set(book.readingListId);
    this.epubReaderPageCount.set(book.pageCount);
  }

  closeEpubReader(): void {
    this.epubReaderKey.set(null);
    this.epubReaderTitle.set('');
    this.epubReaderListId.set(null);
    this.epubReaderPageCount.set(null);
    this.loadLibrary();
  }

  onProgressChanged(currentPage: number): void {
    const key = this.epubReaderKey();
    if (!key) return;
    this.library.update(lib =>
      lib.map(b => {
        if (b.olId !== key) return b;
        return { ...b, currentPage, status: this.resolveStatus(b, currentPage) };
      }),
    );
  }

  changeCurrentPage(book: LibraryBook, delta: number): void {
    const upper = book.pageCount ?? Infinity;
    const next = Math.max(0, Math.min(upper, book.currentPage + delta));
    if (next === book.currentPage) return;
    this.updatePage(book, next);
  }

  setCurrentPage(book: LibraryBook, event: Event): void {
    const value = parseInt((event.target as HTMLInputElement).value, 10);
    if (isNaN(value)) return;
    const upper = book.pageCount ?? Infinity;
    const next = Math.max(0, Math.min(upper, value));
    this.updatePage(book, next);
  }

  private updatePage(book: LibraryBook, next: number): void {
    const status = this.resolveStatus(book, next);
    this.library.update(lib =>
      lib.map(b =>
        b.readingListId === book.readingListId ? { ...b, currentPage: next, status } : b,
      ),
    );
    this.libraryService.updateProgress(book.readingListId, next).subscribe();
  }

  private resolveStatus(book: LibraryBook, page: number): string {
    if (book.pageCount && page >= book.pageCount) return 'FINISHED';
    if (page > 0) return book.status === 'WANT_TO_READ' ? 'READING' : book.status;
    return book.status;
  }

  removeFromLibrary(book: LibraryBook): void {
    if (!confirm(`Pašalinti „${book.title}" iš bibliotekos?`)) return;
    this.libraryService.removeBook(book.readingListId).subscribe({
      next: async () => {
        this.library.update(lib => lib.filter(b => b.readingListId !== book.readingListId));
        await this.epubStorage.remove(book.olId);
        this.localEpubKeys.update(keys => {
          const next = new Set(keys);
          next.delete(book.olId);
          return next;
        });
      },
      error: () => alert('Nepavyko pašalinti knygos.'),
    });
  }

  countByStatus(status: string): number {
    return this.library().filter(b => b.status === status).length;
  }

  get filteredLibrary(): LibraryBook[] {
    const filter = this.activeFilter();
    if (filter === 'VISI') return this.library();
    return this.library().filter(b => b.status === filter);
  }

  statusLabel(status: string): string {
    const labels: Record<string, string> = {
      READING: 'Skaitau',
      WANT_TO_READ: 'Noriu skaityti',
      FINISHED: 'Perskaičiau',
    };
    return labels[status] ?? status;
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}

import {
  Component,
  Input,
  Output,
  EventEmitter,
  AfterViewInit,
  OnDestroy,
  ElementRef,
  ViewChild,
  inject,
  NgZone,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { EpubStorageService } from '../../services/epub-storage.service';
import { LibraryService } from '../../services/library.service';
import { AuthService } from '../../services/auth.service';
import ePub from 'epubjs';

@Component({
  selector: 'app-epub-reader',
  imports: [CommonModule],
  templateUrl: './epub-reader.component.html',
  styleUrl: './epub-reader.component.scss',
})
export class EpubReaderComponent implements AfterViewInit, OnDestroy {
  @Input() bookKey!: string;
  @Input() title = '';
  @Input() readingListId!: number;
  @Input() pageCount: number | null = null;
  @Output() close = new EventEmitter<void>();
  @Output() progressChanged = new EventEmitter<number>();

  @ViewChild('viewer') viewerRef!: ElementRef<HTMLDivElement>;

  private readonly epubStorage = inject(EpubStorageService);
  private readonly libraryService = inject(LibraryService);
  private readonly authService = inject(AuthService);
  private readonly zone = inject(NgZone);

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private book: any = null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private rendition: any = null;
  private blobUrl: string | null = null;
  private keyHandler = this.onKeydown.bind(this);
  private static readonly SETTINGS_KEY_PREFIX = 'epub-reader-settings';
  private static readonly POSITION_KEY_PREFIX = 'epub-reader-position';
  private totalEpubPages = 0;

  isLoading = signal(true);
  error = signal('');
  theme = signal<'light' | 'dark'>(this.loadSettings().theme);
  fontSize = signal(this.loadSettings().fontSize);
  showSettings = signal(false);
  showToc = signal(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  toc = signal<any[]>([]);

  ngAfterViewInit(): void {
    document.addEventListener('keydown', this.keyHandler);
    this.loadEpub();
  }

  private async loadEpub(): Promise<void> {
    try {
      console.log('[EPUB] 1. Loading file from IndexedDB, key:', this.bookKey);
      const file = await this.epubStorage.load(this.bookKey);
      console.log('[EPUB] 2. File loaded:', file ? `${(file as Blob).size} bytes` : 'NULL');

      if (!file) {
        this.zone.run(() => {
          this.error.set('EPUB failas nerastas. Bandykite prisegti failą iš naujo.');
          this.isLoading.set(false);
        });
        return;
      }

      console.log('[EPUB] 3. Converting to ArrayBuffer...');
      const arrayBuffer = await (file as Blob).arrayBuffer();
      console.log('[EPUB] 4. ArrayBuffer size:', arrayBuffer.byteLength);

      console.log('[EPUB] 5. Creating ePub book...');
      this.book = ePub(arrayBuffer);

      console.log('[EPUB] 6. Waiting for book.ready...');
      await this.book.ready;
      console.log('[EPUB] 7. Book ready!');

      const el = this.viewerRef.nativeElement;
      console.log('[EPUB] 8. Viewer element:', el.tagName, 'size:', el.clientWidth, 'x', el.clientHeight);

      this.rendition = this.book.renderTo(el, {
        width: el.clientWidth || 600,
        height: el.clientHeight || 500,
      });
      console.log('[EPUB] 9. Rendition created, calling display()...');

      const savedCfi = this.loadPosition();
      await this.rendition.display(savedCfi || undefined);
      console.log('[EPUB] 10. Display complete!');

      this.applyTheme(this.theme());
      this.applyFontSize(this.fontSize());

      await this.book.locations.generate(1024);
      this.totalEpubPages = this.book.locations.length();

      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      this.rendition.on('relocated', (location: any) => {
        const cfi = location?.start?.cfi;
        if (cfi) {
          this.savePosition(cfi);
          this.syncProgress(location);
        }
      });

      const navigation = await this.book.loaded.navigation;
      this.zone.run(() => {
        this.toc.set(navigation.toc || []);
        this.isLoading.set(false);
      });
    } catch (err) {
      console.error('[EPUB] ERROR at some step:', err);
      this.zone.run(() => {
        this.error.set('Nepavyko atidaryti EPUB failo.');
        this.isLoading.set(false);
      });
    }
  }

  prevPage(): void {
    this.rendition?.prev();
  }

  nextPage(): void {
    this.rendition?.next();
  }

  toggleSettings(): void {
    this.showSettings.update(v => !v);
    if (this.showSettings()) this.showToc.set(false);
  }

  toggleToc(): void {
    this.showToc.update(v => !v);
    if (this.showToc()) this.showSettings.set(false);
  }

  goToChapter(href: string): void {
    this.rendition?.display(href);
    this.showToc.set(false);
  }

  setTheme(theme: 'light' | 'dark'): void {
    this.theme.set(theme);
    this.applyTheme(theme);
    this.saveSettings();
  }

  changeFontSize(delta: number): void {
    const next = Math.min(180, Math.max(60, this.fontSize() + delta));
    this.fontSize.set(next);
    this.applyFontSize(next);
    this.saveSettings();
  }

  private applyTheme(theme: 'light' | 'dark'): void {
    if (!this.rendition) return;
    if (theme === 'dark') {
      this.rendition.themes.override('color', '#ccc');
      this.rendition.themes.override('background', '#1a1a2e');
    } else {
      this.rendition.themes.override('color', '#000');
      this.rendition.themes.override('background', '#fff');
    }
  }

  private applyFontSize(size: number): void {
    if (!this.rendition) return;
    this.rendition.themes.fontSize(`${size}%`);
  }

  private onKeydown(e: KeyboardEvent): void {
    if (e.key === 'ArrowLeft') this.prevPage();
    else if (e.key === 'ArrowRight') this.nextPage();
    else if (e.key === 'Escape') this.zone.run(() => this.onClose());
  }

  private get userPrefix(): string {
    return this.authService.currentUsername() ?? 'default';
  }

  private get settingsKey(): string {
    return `${EpubReaderComponent.SETTINGS_KEY_PREFIX}-${this.userPrefix}`;
  }

  private get positionKey(): string {
    return `${EpubReaderComponent.POSITION_KEY_PREFIX}-${this.userPrefix}-${this.bookKey}`;
  }

  private loadSettings(): { theme: 'light' | 'dark'; fontSize: number } {
    try {
      const raw = localStorage.getItem(this.settingsKey);
      if (raw) return JSON.parse(raw);
    } catch { /* ignore */ }
    return { theme: 'light', fontSize: 100 };
  }

  private saveSettings(): void {
    localStorage.setItem(
      this.settingsKey,
      JSON.stringify({ theme: this.theme(), fontSize: this.fontSize() }),
    );
  }

  private loadPosition(): string | null {
    try {
      return localStorage.getItem(this.positionKey);
    } catch { return null; }
  }

  private savePosition(cfi: string): void {
    localStorage.setItem(this.positionKey, cfi);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private syncProgress(location: any): void {
    if (this.totalEpubPages === 0) return;
    const epubPage = location.start?.location ?? 0;
    const realPage = this.pageCount
      ? Math.round((epubPage / this.totalEpubPages) * this.pageCount)
      : epubPage;
    this.progressChanged.emit(realPage);
    this.libraryService.updateProgress(this.readingListId, realPage).subscribe();
  }

  onClose(): void {
    this.close.emit();
  }

  ngOnDestroy(): void {
    document.removeEventListener('keydown', this.keyHandler);
    this.rendition?.destroy();
    this.book?.destroy();
    if (this.blobUrl) URL.revokeObjectURL(this.blobUrl);
  }
}

import { Component, computed, inject, OnDestroy, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { debounceTime, distinctUntilChanged, switchMap, takeUntil, catchError } from 'rxjs/operators';
import { of } from 'rxjs';
import { BookSearchService, BookSearchResult } from '../../services/book-search.service';
import { LibraryService, LibraryBook } from '../../services/library.service';
import { GoalService, GoalResponse } from '../../services/goal.service';

@Component({
  selector: 'app-home',
  imports: [CommonModule, FormsModule],
  templateUrl: './home.html',
  styleUrl: './home.scss',
})
export class Home implements OnDestroy {
  private readonly bookSearch = inject(BookSearchService);
  private readonly libraryService = inject(LibraryService);
  private readonly goalService = inject(GoalService);
  private readonly searchSubject = new Subject<string>();
  private readonly destroy$ = new Subject<void>();

  searchQuery = '';
  searchResults: BookSearchResult[] = [];
  isLoading = false;
  hasSearched = false;
  errorMessage = '';

  library = signal<LibraryBook[]>([]);
  addingBookKey = signal<string | null>(null);
  recommendations = signal<BookSearchResult[]>([]);
  recommendationsLoading = signal(false);
  goal = signal<GoalResponse | null>(null);
  settingGoal = signal(false);
  newGoalTarget = 10;

  statsTotal = computed(() => this.library().length);
  statsFinished = computed(() => this.library().filter(b => b.status === 'FINISHED').length);
  statsReading = computed(() => this.library().filter(b => b.status === 'READING').length);
  statsPages = computed(() => this.library().reduce((sum, b) => sum + (b.currentPage ?? 0), 0));

  constructor() {
    this.searchSubject.pipe(
      debounceTime(300),
      distinctUntilChanged(),
      switchMap(query => {
        this.isLoading = true;
        this.hasSearched = true;
        this.errorMessage = '';
        this.searchResults = [];
        return this.bookSearch.search(query).pipe(
          catchError(() => {
            this.errorMessage = 'Nepavyko įkrauti rezultatų. Bandykite dar kartą.';
            return of([]);
          })
        );
      }),
      takeUntil(this.destroy$),
    ).subscribe(results => {
      this.searchResults = results;
      this.isLoading = false;
    });

    this.loadLibrary();
    this.loadGoal();
  }

  loadLibrary(): void {
    this.libraryService.getLibrary().subscribe({
      next: books => {
        this.library.set(books);
        this.loadRecommendations(books);
      },
    });
  }

  loadGoal(): void {
    this.goalService.getGoal().subscribe({
      next: goal => this.goal.set(goal),
    });
  }

  saveGoal(): void {
    if (this.newGoalTarget < 1) return;
    this.goalService.setGoal(this.newGoalTarget).subscribe({
      next: goal => {
        this.goal.set(goal);
        this.settingGoal.set(false);
      },
    });
  }

  private loadRecommendations(books: LibraryBook[]): void {
    const authors = [...new Set(
      books.map(b => b.author).filter((a): a is string => !!a && a.trim().length > 0)
    )];
    if (authors.length === 0) return;

    this.recommendationsLoading.set(true);
    const libraryKeys = new Set(books.map(b => b.olId));
    const unique = new Map<string, BookSearchResult>();
    let completed = 0;
    const toQuery = authors.slice(0, 3);

    for (const author of toQuery) {
      this.bookSearch.search(author, 10).pipe(
        catchError(() => of([] as BookSearchResult[])),
      ).subscribe(results => {
        for (const book of results) {
          if (!libraryKeys.has(book.key) && !unique.has(book.key)) {
            unique.set(book.key, book);
          }
        }
        completed++;
        if (completed === toQuery.length) {
          this.recommendations.set([...unique.values()].slice(0, 10));
          this.recommendationsLoading.set(false);
        }
      });
    }
  }

  addToLibrary(book: BookSearchResult): void {
    this.addingBookKey.set(book.key);
    this.libraryService.addBook({
      olId: book.key,
      title: book.title,
      author: book.authors[0] ?? null,
      coverUrl: book.coverUrl,
      pageCount: book.pageCount,
      status: 'WANT_TO_READ',
      genre: book.genre,
    }).subscribe({
      next: added => {
        this.library.update(lib => [...lib, added]);
        this.addingBookKey.set(null);
      },
      error: err => {
        console.error('Nepavyko pridėti knygos:', err);
        alert(err?.error?.message ?? err?.message ?? 'Nepavyko pridėti knygos.');
        this.addingBookKey.set(null);
      },
    });
  }

  isInLibrary(book: BookSearchResult): boolean {
    return this.library().some(b => b.olId === book.key);
  }

  onSearch(): void {
    const query = this.searchQuery.trim();
    if (!query) return;
    this.searchSubject.next(query);
  }

  onSearchKeydown(event: KeyboardEvent): void {
    if (event.key === 'Enter') this.onSearch();
  }

  clearSearch(): void {
    this.searchQuery = '';
    this.searchResults = [];
    this.hasSearched = false;
    this.errorMessage = '';
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }
}

